<?php

declare(strict_types=1);

namespace App\Calls\Comments;

use App\Contracts\Domains\CallSender;
use App\Data\Comments\CommentList;
use App\Support\CallKey;

/**
 * The signed calls of Comments, generated by php artisan journal:calls; run it again instead of editing.
 */
final readonly class CommentCalls
{
    public function __construct(private CallSender $sender) {}

    public function listComments(
        string $target,
        string|null $after = null,
        int|null $perPage = null,
    ): CommentList {
        return $this->sender->send(ListCommentsCall::from([
            'target' => $target,
            'after' => $after,
            'perPage' => $perPage,
        ]));
    }

    public function locateComment(
        string $target,
        string $comment,
        int|null $firstLine = null,
        int|null $lastLine = null,
    ): CommentLocated {
        return $this->sender->send(LocateCommentCall::from([
            'target' => $target,
            'comment' => $comment,
            'firstLine' => $firstLine,
            'lastLine' => $lastLine,
        ]));
    }

    public function postComment(
        string $target,
        string $body,
        string $submissionKey,
        CallKey $requestKey = new CallKey(),
        CommentPlace|null $place = null,
    ): CommentPosted {
        return $this->sender->send(PostCommentCall::from([
            'target' => $target,
            'body' => $body,
            'submissionKey' => $submissionKey,
            'requestKey' => $requestKey,
            'place' => $place,
        ]));
    }
}
